<script setup lang="ts">
import { computed, nextTick, onMounted, ref } from 'vue';
import { X, ListTodo, Lightbulb, NotebookPen, CircleDollarSign, Plus, ChevronDown } from 'lucide-vue-next';
import { request } from '../lib/api';
const props=defineProps<{initialType:string;lookups:any;settings:any;today:string}>();
const emit=defineEmits<{close:[];saved:[]}>();
const dialog=ref<HTMLDialogElement>();const firstInput=ref<HTMLInputElement>();const type=ref(props.initialType);const expanded=ref(false);const busy=ref(false);const errors=ref<Record<string,string[]>>({});const failure=ref('');
const form=ref({title:'',body:'',amount:'',category_id:'',account_id:props.settings.default_finance_account_id||props.lookups.accounts?.[0]?.id||'',description:'',transaction_date:props.today,project_id:'',priority:'normal',planned_date:'',due_at:''});
const options=[{key:'tasks',label:'Task',icon:ListTodo},{key:'ideas',label:'Idea',icon:Lightbulb},{key:'notes',label:'Note',icon:NotebookPen},{key:'transactions',label:'Expense',icon:CircleDollarSign}];
const accountCurrency=computed(()=>props.lookups.accounts?.find((a:any)=>a.id===form.value.account_id)?.currency||props.settings.currency||'IDR');
const amountStep=computed(()=>['IDR','JPY','KRW'].includes(accountCurrency.value)?'1':'0.01');
const categories=computed(()=>(props.lookups.categories||[]).filter((c:any)=>c.type==='expense'));
onMounted(async()=>{dialog.value?.showModal();await nextTick();firstInput.value?.focus();});
async function save(){busy.value=true;errors.value={};failure.value='';try{let payload:any={title:form.value.title};if(type.value==='tasks')payload={...payload,project_id:form.value.project_id||null,priority:form.value.priority,planned_date:form.value.planned_date||null,due_at:form.value.due_at||null};if(type.value==='ideas')payload={...payload,body:form.value.body,status:'inbox'};if(type.value==='notes')payload={...payload,body:form.value.body};if(type.value==='transactions')payload={type:'expense',amount:form.value.amount,category_id:form.value.category_id,account_id:form.value.account_id,transaction_date:form.value.transaction_date,description:form.value.description};await request(`/data/${type.value}`,'POST',payload);emit('saved');}catch(e:any){errors.value=e.errors||{};failure.value=e.message;}finally{busy.value=false;}}
</script>
<template>
 <dialog ref="dialog" class="form-dialog capture-dialog" @cancel.prevent="!busy&&emit('close')"><form @submit.prevent="save">
  <div class="dialog-header"><div><span class="eyebrow">MAKE ROOM IN YOUR MIND</span><h2>Quick Capture</h2></div><button type="button" class="btn-icon" aria-label="Close Quick Capture" :disabled="busy" @click="emit('close')"><X :size="20"/></button></div>
  <div class="dialog-body"><div class="capture-tabs"><button v-for="option in options" :key="option.key" type="button" :class="{active:type===option.key}" @click="type=option.key;errors={};failure='' "><component :is="option.icon" :size="18"/>{{option.label}}</button></div>
   <p v-if="failure" class="error-banner" role="alert">{{failure}}</p>
   <template v-if="type!=='transactions'"><label class="form-field"><span>{{type==='tasks'?'What needs to get done?':type==='ideas'?'What’s on your mind?':'Title (optional)'}}</span><input ref="firstInput" v-model="form.title" maxlength="255" :required="type!=='notes'" :placeholder="type==='tasks'?'e.g. Practice English for 30 minutes':type==='ideas'?'Give your idea a name':'A name for your note'"/><small v-if="errors.title" class="field-error">{{errors.title[0]}}</small></label><label v-if="type==='notes'||type==='ideas'" class="form-field"><span>{{type==='notes'?'Your note':'A little more context (optional)'}}</span><textarea v-model="form.body" rows="5" :required="type==='notes'&&!form.title" placeholder="Capture it while it’s fresh..."/><small v-if="errors.body" class="field-error">{{errors.body[0]}}</small></label>
   <template v-if="type==='tasks'"><label class="checkbox-label"><input type="checkbox" :checked="form.planned_date===today" @change="form.planned_date=($event.target as HTMLInputElement).checked?today:''"/>Plan for today</label><button type="button" class="text-button more-details" @click="expanded=!expanded">{{expanded?'Fewer details':'Add details'}} <ChevronDown :size="14"/></button><div v-if="expanded" class="form-grid"><label class="form-field"><span>Project</span><select v-model="form.project_id"><option value="">No project</option><option v-for="p in lookups.projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label class="form-field"><span>Priority</span><select v-model="form.priority"><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></label><label class="form-field full-width"><span>Due date and time</span><input type="datetime-local" v-model="form.due_at"/><small v-if="errors.due_at" class="field-error">{{errors.due_at[0]}}</small></label></div></template></template>
   <template v-else><div class="form-grid"><label class="form-field full-width"><span>Amount ({{accountCurrency}})</span><input ref="firstInput" v-model="form.amount" type="number" inputmode="decimal" :min="amountStep" :step="amountStep" required placeholder="35000"/><small v-if="errors.amount" class="field-error">{{errors.amount[0]}}</small></label><label class="form-field"><span>Category</span><select v-model="form.category_id" required><option value="" disabled>Choose category</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select><small v-if="errors.category_id" class="field-error">{{errors.category_id[0]}}</small></label><label class="form-field"><span>Account</span><select v-model="form.account_id" required><option value="" disabled>Choose account</option><option v-for="a in lookups.accounts" :key="a.id" :value="a.id">{{a.name}} ({{a.currency}})</option></select><small v-if="errors.account_id" class="field-error">{{errors.account_id[0]}}</small></label><label class="form-field"><span>Date</span><input type="date" v-model="form.transaction_date" required/></label><label class="form-field"><span>Description (optional)</span><input v-model="form.description" placeholder="e.g. Lunch"/></label></div><p v-if="!lookups.accounts?.length" class="form-help">Add a finance account in Finance before recording an expense.</p></template>
  </div><div class="dialog-footer"><span class="muted small-text">{{type==='transactions'?'Recorded in your finances':'Everything has a place.'}}</span><button class="btn btn-primary" :disabled="busy"><Plus v-if="!busy" :size="16"/>{{busy?'Saving...':'Capture '+(options.find(o=>o.key===type)?.label.toLowerCase())}}</button></div>
 </form></dialog>
</template>
